        key = key.strip()
        value = value.strip()
        # An inline comment starts at a hash preceded by whitespace.
        for index, char in enumerate(value):
            if char == \"#\" and index > 0 and value[index - 1].isspace():
                value = value[:index].rstrip()
                break
        if key and value:
            result[key] = value
    return result
